import{_ as t}from"./chunks/emo.Cly4kUfc.js";import{_ as o,o as a,c as r,a5 as n}from"./chunks/framework.BjM_ivYE.js";const g=JSON.parse('{"title":"5. Emergency Stop & Recovery","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"guides/common/emo.md","filePath":"guides/common/emo.md","lastUpdated":1790654527000}'),s={name:"guides/common/emo.md"};function i(l,e,c,h,p,m){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="_5-emergency-stop-recovery" tabindex="-1">5. Emergency Stop &amp; Recovery <a class="header-anchor" href="#_5-emergency-stop-recovery" aria-label="Permalink to &quot;5. Emergency Stop &amp; Recovery&quot;">​</a></h1><p><strong>Goal:</strong> Know how to stop the robot immediately in an emergency and how to safely resume operation.</p><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>Always keep the emergency stop button accessible during operation. In any situation where the robot poses a risk to people or property, press the emergency stop button immediately.</p></div></div><h2 id="physical-emergency-stop-button" tabindex="-1">Physical Emergency Stop Button <a class="header-anchor" href="#physical-emergency-stop-button" aria-label="Permalink to &quot;Physical Emergency Stop Button&quot;">​</a></h2><figure><img src="'+t+'" alt="Emergency stop button on the rear of the robot"><figcaption style="text-align:center;">[ Emergency stop push button — located on the rear of the robot ]</figcaption></figure><p>When the <strong>emergency stop button</strong> is pressed:</p><ul><li>All joints switch to <strong>High Damping</strong> mode.</li><li>The robot resists external motion but does <strong>not</strong> accept torque or position commands.</li><li>The robot may lose its posture and settle to the ground under gravity.</li></ul><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>High Damping mode protects both the user and the robot. The robot will not execute any motion commands until the emergency stop is cleared and the robot is re-initialized.</p></div></div><h2 id="emergency-stop-from-the-app" tabindex="-1">Emergency stop from the app <a class="header-anchor" href="#emergency-stop-from-the-app" aria-label="Permalink to &quot;Emergency stop from the app&quot;">​</a></h2><p>The RBQ app has an <code>E-STOP</code> button at the right of the top bar on the control home, and in the same place on the other screens while a robot is connected — if the link drops it stays live for 8 seconds. It asks for confirmation and then has the same effect as the physical button — all joints enter High Damping mode. See <strong><a href="/RBQ/manual/gui/emergency.html">Emergency Stop</a></strong> for the confirmation dialog and what happens when another device takes control; the forced-recovery tools are on <strong><a href="/RBQ/manual/gui/developer-mode.html#emergency">Developer mode</a></strong>.</p><h2 id="recovery-procedure" tabindex="-1">Recovery Procedure <a class="header-anchor" href="#recovery-procedure" aria-label="Permalink to &quot;Recovery Procedure&quot;">​</a></h2><p>After an emergency stop, follow these steps to safely resume operation:</p><ol><li><strong>Ensure safety</strong> — Confirm that all people and animals have moved at least 2 m away from the robot.</li><li><strong>Release the button</strong> — Rotate the physical emergency stop button clockwise to return it to its original (unlocked) position.</li><li><strong>Return to initial pose</strong> — If the robot has fallen or shifted, manually return it to the <a href="/RBQ/guides/common/initial-pose.html">correct initial pose</a> on a flat surface.</li><li><strong>Re-initialize</strong> — Run the automatic start sequence or the Stand motion from the <a href="/RBQ/manual/gui/control-home.html">control home</a>.</li><li><strong>Verify</strong> — Confirm that the robot state in the top bar is normal and that every start item has completed before resuming operation.</li></ol><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Do not attempt to force-move the joints while the robot is in High Damping mode. Return the robot to the initial pose carefully and only after the emergency stop has been released.</p></div></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/RBQ/manual/safety/general-safety-warning-precautions.html">General Safety Guidelines</a></li><li><a href="/RBQ/manual/safety/emergency-stop-procedures.html">Emergency Stop Procedures (detailed)</a></li><li><a href="/RBQ/guides/common/initial-pose.html">Initial Pose &amp; Power On</a></li></ul>',16)])])}const y=o(s,[["render",i]]);export{g as __pageData,y as default};
